class Solution:
    def removeOuterParentheses(self, S: str) -> str:
        result = []
        count = 0
        for char in S:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            else:
                if count > 0:
                    result.append(char)
        return ''.join(result)
